# -*- coding: utf-8 -*-
"""Build the complete atlas with the Python standard library."""
from common import *
from content import DESCRIPTIONS
from catalog import TOOLS,GROUPS
from diagrams import synthetic_map

def overview(lang):
    t=lambda en,zh:pick(lang,en,zh)
    steps=[('01','OBSERVE','观察',t('Record what is actually visible','记录实际可见内容')),('02','LOCATE','定位',t('Compare geometry, views and dates','比较几何、视角与日期')),('03','CHALLENGE','质疑',t('Test alternatives and contradictions','检验替代解释与矛盾')),('04','EXPLAIN','解释',t('Keep sources, scope and uncertainty','保留来源、范围与不确定性'))]
    graphic='<aside class="trust-map" aria-label="'+t('Investigation workflow','调查流程')+'"><div class="map-label">FROM PUBLIC INFORMATION TO EVIDENCE</div>'+''.join(f'<div class="map-step"><span>{n}</span><div><strong>{t(en,zh)}</strong><small>{desc}</small></div></div>' for n,en,zh,desc in steps)+'<div class="map-foot">'+t('A good answer can still contain unknowns','好的答案仍可包含未知项')+'</div></aside>'
    body='<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">OPEN SOURCES / GEOGRAPHY / EVIDENCE</span><h1>'+t('Read the clues<br><em>Test the location</em>','读懂线索<br><em>核验地点</em>')+'</h1><p>'+t('An independent learning atlas for open-source intelligence, with a deep GEO track: search, verify images, compare maps and terrain, resolve coordinates, and explain conclusions that another reader can check.','独立的开源情报学习地图，重点深入 GEO：检索信息、核验图像、比较地图与地形、处理坐标，并给出其他读者能够检查的结论。')+'</p><div class="hero-actions"><a class="button" href="'+href('geo',lang)+'">'+t('Explore the GEO workflow →','进入 GEO 流程 →')+'</a><a class="text-link" href="'+href('tools',lang)+'">'+t('Find a tool ↗','查找工具 ↗')+'</a></div><div class="hero-meta">19 SECTIONS / 14 DIAGRAMS / 3 LOCAL EXERCISES<br>'+t('ENGLISH & 中文 · ORIGINAL GUIDES · SOURCE LINKS','中英双语 · 原创导读 · 来源链接')+'</div></div>'+graphic+'</div></section><div class="reading wrap">'
    route=[('01',t('Build an evidence habit','建立证据习惯'),t('Foundations → Collection → Media → Evidence. Produce a source ledger distinguishing the original, copies, observations and inferences.','基础 → 采集 → 媒体 → 证据。产出区分原件、副本、观察与推断的台账。')),('02',t('Learn to narrow the map','学会缩小地图'),t('GEO workflow → Visual clues → Maps & OSM. Sketch the scene, generate candidates and record spatial contradictions.','GEO 流程 → 视觉线索 → 地图与 OSM。画出场景、生成候选并记录空间矛盾。')),('03',t('Add time, terrain and coordinate discipline','加入时间、地形与坐标方法'),t('Satellite → Terrain → Time & shadows → Coordinates. Check sensor limits, imagery dates, viewpoint and coordinate order.','卫星 → 地形 → 时间与阴影 → 坐标。检查传感器限制、影像日期、视点及坐标顺序。')),('04',t('Publish a reviewable result','形成可审查结果'),t('Entities → Analysis → AI assistance → Projects / Labs. Keep alternatives, independent evidence and the uncertainty of each claim.','实体 → 分析 → AI 辅助 → 项目 / 练习。保留替代解释、独立证据及逐项主张不确定性。'))]
    body+=section('01 / LEARNING ROUTE',t('A route from clues to a defensible answer','从线索到有依据答案的路径'),t('For engineers and security learners. No specialist GIS background is required; start with the GEO workflow if you already know basic research methods.','面向工程师与安全学习者，无需专业 GIS 背景。已熟悉基础研究方法时，可直接从 GEO 流程开始。'),'<div class="sequence">'+''.join(f'<article><span>{n}</span><div><h3>{title}</h3><p>{text}</p></div></article>' for n,title,text in route)+'</div>','route')
    grid='<div class="topic-grid">'+''.join(f'<a class="topic-card" href="{href(page,lang)}"><span class="eyebrow">{i:02} / FIELD NOTES</span><h3>{NAV[lang][i]}</h3><p>{desc[1 if lang=="zh" else 0]}</p></a>' for i,(page,desc) in enumerate(zip(PAGES[1:],DESCRIPTIONS),1))+'</div>'
    body+=section('02 / CHAPTERS',t('Choose an investigation question','选择一个调查问题'),t('Methods, GEO analysis and tools are organized as one independent learning direction. Read sequentially or enter at the question you need.','方法、GEO 分析与工具组成独立学习方向。可以顺序阅读，也可从具体问题进入。'),grid,'chapters')
    body+=section('03 / PRACTICE',t('Keep four useful outputs','保留四项有用产出'),t('The aim is an investigation that can be checked, not a pile of bookmarks.','目标是可以核验的调查，而不只是收藏夹。'),cards([('OBSERVATIONS',t('A clue sheet','线索表'),t('Literal observations, uncertain text, geometry and camera direction.','字面观察、不确定文字、几何关系与镜头方向。')),('CANDIDATES',t('A candidate matrix','候选矩阵'),t('Matches, contradictions and missing checks for more than one hypothesis.','多个假设的匹配、矛盾及缺少核验。')),('PROVENANCE',t('An evidence ledger','证据台账'),t('Source IDs, acquisition time, originals, transformations and independent roots.','来源编号、采集时间、原件、转换及独立根来源。')),('REPORT',t('A bounded conclusion','有范围的结论'),t('A point, segment, region or unresolved answer with explicit reasons.','有理由的点、区间、区域或未解决答案。'))]),'outputs')
    body+=callout(t('Access notes are part of the toolkit','访问说明也是工具目录的一部分'),t('Links and access notes reviewed on 1 Oct 2026. Coverage, accounts and prices can change. The course remains readable without third-party logins; the three synthetic exercises run locally without uploads or map APIs.','链接及访问说明复核于 2026 年 10 月 1 日；覆盖、账号及价格可能变化。课程正文无需第三方登录；三项合成练习在本地运行，不上传数据、不调用地图 API。'))
    return body+'</div>'

def chapter_page(page,lang):
    t=lambda en,zh:pick(lang,en,zh)
    rows=chapter(page,lang);idx=PAGES.index(page)
    body=hero(lang,page,NAV[lang][idx]+'<br><em>'+t('From clues to evidence','从线索到证据')+'</em>',DESCRIPTIONS[idx-1][1 if lang=='zh' else 0],[(r[0],r[1]) for r in rows])+'<div class="reading wrap">'
    for i,(ident,title,intro,content,refs,viz) in enumerate(rows,1):body+=section(f'{i:02} / FIELD NOTES',title,intro,(diagram(viz,lang) if viz else '')+content+(cite(lang,*refs) if refs else ''),ident)
    body+=callout(t('Check your understanding','检查理解'),t('Choose one claim from a public-landmark example. State the observation, inference, supporting source, possible contradiction and the next check needed.','选择公共地标例子的一项主张，指出观察、推断、支持来源、潜在矛盾及下一项所需核验。'))
    return body+'</div>'

def tools_page(lang):
    t=lambda en,zh:pick(lang,en,zh)
    body=hero(lang,'tools',t('Choose by question<br><em>Read the limitations</em>','按问题选工具<br><em>阅读使用限制</em>'),t('A searchable directory of '+str(len(TOOLS))+' original resources. Map sites, method guides and local tools have different roles. Each entry states a useful question and a limitation.','可搜索的 '+str(len(TOOLS))+' 项原始资源目录。地图网站、方法指南与本地工具作用不同；每项给出适用问题与限制。'))+'<div class="reading wrap"><section class="chapter-section">'
    body+='<div class="tool-filter"><label for="tool-search">'+t('Search name, use or limitation','搜索名称、用途或限制')+'</label><input type="search" id="tool-search" placeholder="'+t('e.g. Street View, metadata, shadow','例如街景、元数据、阴影')+'"><label for="tool-category">'+t('Category','类别')+'</label><select id="tool-category"><option value="all">'+t('All categories','所有类别')+'</option>'+''.join(f'<option value="{k}">{v[1 if lang=="zh" else 0]}</option>' for k,v in GROUPS.items())+'</select><p id="tool-count" role="status" aria-live="polite">'+t(str(len(TOOLS))+' resources',str(len(TOOLS))+' 项资源')+'</p></div><div class="tool-grid">'
    for ident,name,url,group,en,zh,limen,limzh in TOOLS:body+=f'<article class="tool-card" data-category="{group}"><span class="eyebrow">{GROUPS[group][1 if lang=="zh" else 0]}</span><h3>{escape(name)}</h3><p>{t(en,zh)}</p><small>{t(limen,limzh)}</small><a href="{url}" target="_blank" rel="noopener noreferrer">'+t('Open original resource ↗','打开原始资源 ↗')+'</a></article>'
    return body+'</div><p id="tool-empty" hidden>'+t('No matching resources. Try another word or category.','无匹配资源，请尝试其他词或类别。')+'</p></section>'+callout(t('If a tool is unavailable','工具无法访问时'),t('Use the same evidence type from another original provider: another ground view, an official local map, a satellite scene or a local metadata tool. A second website does not automatically mean a second independent dataset. Check dates, attribution and source lineage.','从另一原始提供者获取同类证据：另一地面视图、本地官方地图、卫星场景或本地元数据工具。第二个网站不自动意味着第二个独立数据集；检查日期、署名与来源链。'))+'</div>'

def sources_page(lang):
    t=lambda en,zh:pick(lang,en,zh)
    body=hero(lang,'sources',t('Read original sources<br><em>Keep a method notebook</em>','阅读原始资料<br><em>保留方法笔记</em>'),t('Primary method guides, official documentation and source services. Every external link opens the original publisher; the atlas does not mirror maps or third-party images.','原始方法指南、官方文档及来源服务。外链打开原始发布者；本站不镜像地图或第三方图片。'))+'<div class="reading wrap">'
    for i,(group,(en,zh)) in enumerate(GROUPS.items(),1):
        grid='<div class="source-grid">'+''.join(f'<a class="source-card" href="{url}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">{t("ORIGINAL PUBLISHER","原始发布者")}</span><h3>{escape(name)} ↗</h3><p>{t(limen,limzh)}</p></a>' for ident,name,url,g,enq,zhq,limen,limzh in TOOLS if g==group)+'</div>'
        body+=section(f'{i:02} / SOURCES',t(en,zh),t('Read the related chapter first, then check the original interface and assumptions.','先阅读相关章节，再核对原始界面与假设。'),grid,group)
    body+=callout(t('Dates and availability','日期与可用性'),t('Reviewed 1 Oct 2026. A successful link check does not guarantee access from every network or account. The NOAA legacy calculator is marked as unmaintained; Copernicus Browser is marked as requiring a free account. ExifTool links to the official repository as a robust documentation fallback.','复核于 2026 年 10 月 1 日。链接检查成功不保证所有网络或账号都可访问。NOAA 旧计算器标注停止维护，Copernicus Browser 标注需要免费账号；ExifTool 提供官方仓库作为稳健文档替代入口。'))
    return body+'</div>'

def labs_page(lang):
    t=lambda en,zh:pick(lang,en,zh)
    body=hero(lang,'labs',t('Try the method<br><em>Inspect the uncertainty</em>','尝试方法<br><em>观察不确定性</em>'),t('Three deterministic exercises use invented scenes and records. Everything runs in this page: no uploads, external APIs or saved exercise data.','三项确定性练习使用虚构场景与记录。所有计算在本页完成：不上传、不调用外部 API、不保存练习数据。'),[('candidate',t('Candidate test','候选检验')),('lineage',t('Source roots','来源根')),('coordinate',t('Coordinate check','坐标检查'))])+'<div class="reading wrap"><noscript><aside class="callout">'+t('Enable JavaScript for the exercises. Chapter explanations remain available.','启用 JavaScript 使用练习；章节正文仍可阅读。')+'</aside></noscript>'
    def select(ident,label,options):return f'<label for="{ident}">{label}<select id="{ident}">'+''.join(f'<option value="{v}">{text}</option>' for v,text in options)+'</select></label>'
    def box(ident,controls,label):return f'<div class="lab-box"><div class="scenario-options">{controls}</div><div class="lab-actions"><button type="button" data-action="{ident}">{label}</button></div><p class="lab-state" data-pass="info" id="{ident}-state" role="status" aria-live="polite">'+t('Ready — choose an input','就绪 — 选择输入')+f'</p><div class="lab-output" id="{ident}-output"></div></div>'
    gallery='<div class="candidate-grid">'+''.join('<figure>'+synthetic_map(lang,c)+'<figcaption>'+t('Candidate ','候选 ')+c+'</figcaption></figure>' for c in 'ABC')+'</div>'
    controls=select('candidate-choice',t('Candidate','候选'),[(c,c) for c in 'ABC'])+select('candidate-check',t('Independent ground-view check','独立地面视图核验'),[('missing',t('Not available','尚未取得')),('verified',t('Verified geometry match','已核验几何吻合'))])
    body+=section('01 / GEO',t('Eliminate contradictions before adding confidence','提升置信度前先排除矛盾'),t('Known scene: north–south river, east–west bridge, building on the east bank north of the bridge, T-junction east of the bridge. The source is verified as not mirrored.','已知场景：南北河流、东西桥梁、建筑位于桥北河东、桥东有丁字路口；来源已核验无镜像。'),gallery+box('candidate',controls,t('Compare the candidate','比较候选'))+para(t('The maps are synthetic and north-up. The selected ground check is a teaching input, not a real service call. A visual fit with no independent check remains a plausible candidate; a new ground match cannot erase an existing topology contradiction.','地图为合成且北向朝上。所选地面核验是教学输入，不是真实服务调用。缺少独立核验时，视觉吻合仍是合理候选；新增地面匹配也不能抹去现有拓扑矛盾。')),'candidate')
    controls=select('lineage-choice',t('Available material','现有资料'),[('reposts',t('Original X + two reposts','原始 X + 两次转发')),('camera',t('Original X + independent camera Y','原始 X + 独立相机 Y')),('map',t('Original X + independent dated map','原始 X + 独立有日期地图')),('model',t('Original X + two model guesses','原始 X + 两个模型猜测'))])+select('lineage-claim',t('Claim being checked','正在检查的主张'),[('geometry',t('The scene geometry matches','场景几何吻合')),('event',t('The depicted event occurred','画面中的事件发生过'))])
    body+=section('02 / PROVENANCE',t('Count observation roots for a specific claim','针对具体主张统计观察根'),t('X is one photo of a scene and event. Y is a separate simultaneous camera recording the same event from another angle. The map records site geometry only. Model guesses use X as input.','X 为场景及事件的一张照片；Y 是另一相机从不同角度同时记录该事件。地图只记录地点几何。模型猜测以 X 为输入。'),box('lineage',controls,t('Inspect source independence','检查来源独立性'))+para(t('This exercise counts stipulated roots; it does not authenticate them or calculate truth probabilities. In a real case, independence and what each source supports need their own verification.','练习统计设定的来源根，不认证其真实性或计算真实概率。现实案例中独立性及各来源支持内容仍需分别核验。')),'lineage')
    controls='<label class="lab-field" for="coordinate-first">'+t('First value · signed decimal degrees','第一个值 · 带符号十进制度')+'<input type="number" step="any" id="coordinate-first" value="30"></label><label class="lab-field" for="coordinate-second">'+t('Second value · signed decimal degrees','第二个值 · 带符号十进制度')+'<input type="number" step="any" id="coordinate-second" value="120"></label>'+select('coordinate-order',t('Input order','输入顺序'),[('latlon','latitude, longitude'),('lonlat','longitude, latitude')])+select('coordinate-system',t('Reference system','参考体系'),[('wgs','WGS 84'),('unknown',t('Unknown / provider coordinates','未知 / 服务特有坐标'))])
    body+=section('03 / COORDINATES',t('Valid numbers can still describe the wrong place','有效数值仍可能描述错误地点'),t('Normalize a decimal pair and inspect its GeoJSON order. Distance uses the synthetic reference point lat 30°, lon 120° on a spherical Earth of radius 6,371 km.','归一化十进制度数值对，检查 GeoJSON 顺序。距离使用合成参考点纬度 30°、经度 120°，地球简化为半径 6,371 公里的球体。'),box('coordinate',controls,t('Check the coordinate contract','检查坐标约定'))+para(t('Try 30, 120 in both orders, then 45, 60: both orders of the latter pass range checks but differ geographically. Unknown reference systems are not converted. Distance is approximate, not a surveying result; no map or location service is queried.','分别按两种顺序试 30、120，再试 45、60：后者两个顺序都通过范围检查，却是不同地点。未知参考体系不进行转换。距离为近似值，不是测绘结果；不查询地图或定位服务。'))+cite(lang,'geojson','qgis-crs'),'coordinate')
    return body+'</div>'

if __name__=='__main__':
    for lang in ('en','zh'):
        for page in PAGES:
            body=overview(lang) if page=='index' else tools_page(lang) if page=='tools' else sources_page(lang) if page=='sources' else labs_page(lang) if page=='labs' else chapter_page(page,lang)
            (ROOT/href(page,lang)).write_text(shell(lang,page,body),encoding='utf-8')
    print(f'Built {2*len(PAGES)} pages, {len(TOOLS)} catalog resources, 14 bilingual diagrams, 3 local exercises')
